import{sourcePath,sourceBytes,normalizeSource}from'./source-archive.js';import{detectSourceEngine,scanFeatures,applyFeatures,ENGINE_NAMES,runtimeSettings}from'./source-features.js';import{sourceSpriteBytes,installSourceMusic,sourceSongSlots}from'./source-assets.js';import{crc32}from'./zip.js';
export async function sourceDigest(files){const rows=[];for(const[p,b]of [...files].sort(([a],[b])=>a.localeCompare(b))){const hash=await crypto.subtle.digest('SHA-256',b);rows.push(p+':'+Array.from(new Uint8Array(hash),n=>n.toString(16).padStart(2,'0')).join(''));}const hash=await crypto.subtle.digest('SHA-256',sourceBytes(rows.join('\n')));return Array.from(new Uint8Array(hash),n=>n.toString(16).padStart(2,'0')).join('');}
export function makeSourceSettings(engine,archiveId,name){return{version:1,engine,archiveId,name:String(name||ENGINE_NAMES[engine]).slice(0,120),features:{},sprites:[],music:[]};}
export function validateSourceSettings(s){if(s===undefined)return;if(!s||s.version!==1||!Object.hasOwn(ENGINE_NAMES,s.engine)||!/^source-[a-f0-9]{64}$/.test(s.archiveId)||typeof s.name!=='string'||s.name.length>120||!s.features||Array.isArray(s.features)||Object.keys(s.features).length>512||!Array.isArray(s.sprites)||s.sprites.length>256||!Array.isArray(s.music)||s.music.length>128)throw Error('Invalid source-engine settings.');for(const[k,v]of Object.entries(s.features)){if(k.length>600||!k.includes('::')||!(typeof v==='boolean'||Number.isInteger(v)))throw Error('Invalid source feature.');sourcePath(k.split('::')[0]);}const paths=new Set();for(const b of s.sprites){sourcePath(b.path);if(paths.has(b.path)||typeof b.groupId!=='string'||typeof b.role!=='string'||typeof b.shiny!=='boolean')throw Error('Invalid sprite binding.');paths.add(b.path);}const slots=new Set();for(const b of s.music){if(typeof b.trackId!=='string'||typeof b.slot!=='string'||b.slot.length>512||slots.has(b.slot))throw Error('Invalid song binding.');slots.add(b.slot);}}
export function sourceInventory(files,engine=detectSourceEngine(files)){return{engine,features:scanFeatures(files,engine),runtime:runtimeSettings(files,engine),songs:sourceSongSlots(files,engine),graphics:[...files.keys()].filter(p=>/^(graphics|follower_mon_sprites)\/.*\.(png|4bpp|gbapal|pal)(\.lz)?$/.test(p)).sort(),mapCount:[...files.keys()].filter(p=>/^data\/maps\/[^/]+\/map.json$/.test(p)).length};}
export function sourceChanges(a,b){return[...b].flatMap(([path,bytes])=>{const prior=a.get(path);return!prior||prior.length!==bytes.length||prior.some((n,i)=>n!==bytes[i])?[{path,bytes:bytes.length,kind:prior?'modified':'added',before:prior?crc32(prior).toString(16):null,after:crc32(bytes).toString(16)}]:[];});}
export function prepareSourceExport(original,s,project,{songLimit}={}){validateSourceSettings(s);const engine=detectSourceEngine(original);if(engine!==s.engine)throw Error('Attached engine differs from saved settings.');const inventory=sourceInventory(original,engine);let files=applyFeatures(original,inventory.features,s.features);for(const binding of s.sprites){if(!inventory.graphics.includes(binding.path))throw Error('Source graphics file missing: '+binding.path);const g=project.spriteStudio?.groups.find(g=>g.id===binding.groupId);if(!g)throw Error('Bound sprite group missing.');files.set(binding.path,sourceSpriteBytes(g,binding.role,binding.path,original.get(binding.path),binding));}for(const[index,binding]of s.music.entries()){const track=project.authoring?.music?.find(t=>t.id===binding.trackId);if(!track)throw Error('Bound music track missing.');({files}=installSourceMusic(files,engine,track,binding.slot,index,{songLimit}));}files.set('studio/editor-project.pokebacon.json',sourceBytes(JSON.stringify(project,null,2)+'\n'));const report={format:'pokebacon-source-export',version:1,engine,engineName:ENGINE_NAMES[engine],features:s.features,sprites:s.sprites,music:s.music,changes:sourceChanges(original,files).filter(c=>c.path!=='studio/editor-project.pokebacon.json'),editorProjectIncluded:true,originalMapFilesPreserved:true,notes:['Rebuild with the project toolchain on a computer. Android does not contain devkitARM or a full decomp compiler.','The editable project is included at studio/editor-project.pokebacon.json. Its maps/events are not converted to source maps. Referenced external assets still require the original project backup. Rebuild source before binding and exporting binary edits against the rebuilt ROM.','Runtime flags and variables are preserved; compile-time switches do not change saved game state.']};files.set('studio/source-report.json',sourceBytes(JSON.stringify(report,null,2)+'\n'));return{files,report};}
export async function importSourceEntries(entries,name){const files=normalizeSource(entries),engine=detectSourceEngine(files),hash=await sourceDigest(files),settings=makeSourceSettings(engine,'source-'+hash,name);return{files,settings,inventory:sourceInventory(files,engine)};}
